using MiniPharmacie.Business.Models;
using MiniPharmacie.Business.Services;
using MiniPharmacie.Data.Database;

namespace MiniPharmacie.Tests;

public sealed class AdminReportingBackupTests
{
    private static async Task<(DatabaseInitializer Db,long Admin,long Seller,long Product,long Supplier)> Setup(){var db=new DatabaseInitializer(Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".db"));await db.InitializeAsync();await using var c=db.CreateConnection();await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="INSERT INTO Roles(Name) VALUES('Responsable'),('Vendeur');INSERT INTO Users(RoleId,Username,PasswordHash,CreatedAt) VALUES(1,'admin','pbkdf-hash',datetime('now')),(2,'seller','pbkdf-hash',datetime('now'));INSERT INTO Products(Code,Name,Unit,SalePriceMinor,ReorderLevel) VALUES('P','Produit','boîte',300,0);INSERT INTO Suppliers(Name) VALUES('Fournisseur');";await q.ExecuteNonQueryAsync();return(db,1,2,1,1);}
    [Fact] public async Task SellerIsDeniedManagerActionsEvenWithoutUi(){var(db,admin,seller,p,v)=await Setup();var users=new SecurityAdministrationService(db);await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>users.CreateUserAsync(seller,"baduser","MotDePasseTresFort!123","Responsable"));var settings=new PharmacySettingsService(db);await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>settings.SaveAsync(seller,new Dictionary<string,string>{{"Name","X"}}));await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>new ReportingService(db).GetStockReportAsync(seller));await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>new DatabaseBackupService(db).CreateVerifiedBackupAsync(seller));await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>new StockManagementService(db).SaveProductAsync(new("P2","Interdit",null,"","","boîte",400,1,null,null),seller));await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>new StockManagementService(db).ReceiveAsync(new(v,seller,"R-Seller",DateTimeOffset.Now,[new(p,1,100,"Lot-V",null)],null)));}
    [Fact] public async Task ReportsReflectRecordedSales(){var(db,admin,seller,p,v)=await Setup();var stock=new StockManagementService(db);await stock.ReceiveAsync(new(v,admin,"R1",DateTimeOffset.Now,[new(p,8,110,"L1",null)],null));var sales=new SalesAndCashService(db);var session=await sales.OpenCashSessionAsync(seller,0);await sales.CheckoutAsync(new(seller,session,[new(p,"P","Produit",300,2)],[new("ESPECES",600)]));var report=await new ReportingService(db).GetSalesReportAsync(admin,DateOnly.FromDateTime(DateTime.Today),DateOnly.FromDateTime(DateTime.Today));Assert.Contains(report,x=>x.RevenueMinor==600&&x.CostMinor==220&&x.MarginMinor==380);}
    [Fact] public async Task VerifiedBackupRestoresAndInvalidFileDoesNotReplaceDatabase(){var(db,admin,_,_,_)=await Setup();var backupDirectory=Path.GetDirectoryName(db.DatabasePath)!;await using(var c=db.CreateConnection()){await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="INSERT INTO PharmacySettings(Key,Value) VALUES('BackupDirectory',$path) ON CONFLICT(Key) DO UPDATE SET Value=excluded.Value";q.Parameters.AddWithValue("$path",backupDirectory);await q.ExecuteNonQueryAsync();}var backups=new DatabaseBackupService(db);var path=await backups.CreateVerifiedBackupAsync(admin,backupDirectory);await using(var c=db.CreateConnection()){await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="DELETE FROM Products";await q.ExecuteNonQueryAsync();}await backups.RestoreVerifiedBackupAsync(admin,path);await using(var c=db.CreateConnection()){await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="SELECT COUNT(*) FROM Products";Assert.Equal(1L,(long)(await q.ExecuteScalarAsync())!);}var invalid=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".db");await File.WriteAllTextAsync(invalid,"not sqlite");await Assert.ThrowsAnyAsync<Exception>(()=>backups.RestoreVerifiedBackupAsync(admin,invalid));try{await using var c=db.CreateConnection();await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="SELECT COUNT(*) FROM Products";Assert.Equal(1L,(long)(await q.ExecuteScalarAsync())!);}finally{File.Delete(invalid);File.Delete(path);}}
    [Fact] public async Task AuditIsAppendOnly(){var(db,admin,_,_,_)=await Setup();await using var c=db.CreateConnection();await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="INSERT INTO AuditLog(UserId,Action,Entity,OccurredAt) VALUES($u,'TEST','Users',$d)";q.Parameters.AddWithValue("$u",admin);q.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));await q.ExecuteNonQueryAsync();q.CommandText="DELETE FROM AuditLog";await Assert.ThrowsAsync<Microsoft.Data.Sqlite.SqliteException>(()=>q.ExecuteNonQueryAsync());}
    [Fact] public void PasswordHashIsSaltedAndNeverPlain(){var first=MiniPharmacie.Business.Security.PasswordHasher.Hash("UnMotDePasseTresSolide!2026");var second=MiniPharmacie.Business.Security.PasswordHasher.Hash("UnMotDePasseTresSolide!2026");Assert.NotEqual(first,second);Assert.DoesNotContain("UnMotDePasseTresSolide",first);Assert.True(MiniPharmacie.Business.Security.PasswordHasher.Verify("UnMotDePasseTresSolide!2026",first));}
}
